/* @lc app=leetcode id=2456 lang=kotlin */ class Solution { fun mostPopularCreator(creators: Array<String>, ids: Array<String>, views: IntArray): List<List<String>> = creators.indices.groupBy { creators[it] }.mapValues { (_, l) -> l.sumOf { views[it].toLong() } to ids[l.sortedWith(compareBy<Int>({ -views[it] }, { ids[it] })).first()] }.let { m -> m.values.maxOf { it.first }.let { mx -> m.filter { it.value.first == mx }.map { listOf(it.key, it.value.second) } } } }